import datetime as dt
import fcntl
import hashlib
import ipaddress
import json
import os
from pathlib import Path
import pwd
import stat
import subprocess
import sys
import uuid

BASE = Path('/opt/ambrogio-rbx2')
POLICY = Path('/etc/ambrogio-rbx2/p0.json')
LOGDIR = Path('/var/log/ambrogio-rbx2')
ENV = {'PATH':'/usr/sbin:/usr/bin:/sbin:/bin','LANG':'C','LC_ALL':'C','HOME':'/root'}
class Refused(Exception): pass
class CheckError(Exception): pass

def stamp(): return dt.datetime.now(dt.timezone.utc).isoformat()
def sha(b): return hashlib.sha256(b).hexdigest()
def trusted(p, directory=False, private=False):
    p = Path(p)
    for n in [p, *p.parents]:
        s = n.lstat()
        if stat.S_ISLNK(s.st_mode) or s.st_uid != 0 or s.st_mode & 0o022:
            raise Refused('untrusted_path')
        if n != p and not stat.S_ISDIR(s.st_mode): raise Refused('ancestor_type')
    s = p.lstat()
    if directory != stat.S_ISDIR(s.st_mode): raise Refused('path_type')
    if not directory and not stat.S_ISREG(s.st_mode): raise Refused('not_regular')
    if private and s.st_mode & 0o077: raise Refused('not_private')

def schema(p):
    required = {'schema','service','install_id','machine_id','files','nft_semantic',
                'emergency_key','ssh_contexts','allowed_listeners','min_resources',
                'max_update_age_hours','required_units','signer_key'}
    if not isinstance(p,dict) or set(p) != required or p['schema'] != 2:
        raise Refused('policy_schema')
    for k in ('service','install_id','machine_id','emergency_key','signer_key'):
        if not isinstance(p[k],str) or not p[k] or 'DA_' in p[k]: raise Refused('policy_value')
    if not isinstance(p['files'],dict) or not p['files']: raise Refused('file_map')
    for path, digest in p['files'].items():
        if not isinstance(path,str) or not path.startswith(('/opt/ambrogio-rbx2/','/etc/ambrogio-rbx2/','/etc/systemd/system/','/etc/ssh/','/etc/ambrogio-rbx2-reader.json','/etc/apt/','/etc/nftables.conf','/etc/sudoers')):
            raise Refused('file_scope')
        if '..' in Path(path).parts or not isinstance(digest,str) or len(digest)!=64 or any(x not in '0123456789abcdef' for x in digest): raise Refused('file_digest')
    critical={'/etc/apt/ambrogio-ovh.sources','/etc/apt/apt.conf.d/00ambrogio-origins','/opt/ambrogio-rbx2/p0-preflight.py','/opt/ambrogio-rbx2/export-log.py','/opt/ambrogio-rbx2/monitor.py','/opt/ambrogio-rbx2/security-update.py','/etc/ambrogio-rbx2/allowed_signers','/etc/ssh/sshd_config','/etc/ssh/authorized_keys/debian','/etc/nftables.conf','/etc/sudoers','/etc/apt/apt.conf.d/20auto-upgrades','/etc/apt/apt.conf.d/52ambrogio-rbx2','/etc/systemd/system/ambrogio-rbx2-monitor.service','/etc/systemd/system/ambrogio-rbx2-monitor.timer','/etc/systemd/system/ambrogio-rbx2-security.service','/etc/systemd/system/ambrogio-rbx2-security.timer','/etc/systemd/system/ambrogio-rbx2-emergency-ssh.service','/opt/ambrogio-rbx2/read-only.py','/etc/systemd/system/ambrogio-rbx2-reader.service','/etc/systemd/system/ambrogio-rbx2-resume.service','/etc/ambrogio-rbx2/diagnostic-stop.nft','/etc/ambrogio-rbx2-reader.json'}
    if not critical<=set(p['files']): raise Refused('critical_file_missing')
    if not isinstance(p['nft_semantic'],dict): raise Refused('nft_schema')
    if not isinstance(p['ssh_contexts'],list) or len(p['ssh_contexts']) < 2: raise Refused('contexts')
    versions=set()
    for c in p['ssh_contexts']:
        if not isinstance(c,dict) or set(c)!={'addr','laddr','host'}: raise Refused('context_schema')
        a,b=ipaddress.ip_address(c['addr']),ipaddress.ip_address(c['laddr'])
        if a.version != b.version or not c['host'] or any(x not in 'abcdefghijklmnopqrstuvwxyz0123456789.-' for x in c['host']): raise Refused('context_value')
        versions.add(a.version)
    if versions!={4,6}: raise Refused('ipv6_context_missing')
    if not isinstance(p['allowed_listeners'],list) or any(not isinstance(x,list) or len(x)!=3 or any(not isinstance(v,str) for v in x) for x in p['allowed_listeners']): raise Refused('listeners_schema')
    if not isinstance(p['required_units'],list) or not p['required_units'] or any(not isinstance(x,str) or '/' in x or '\n' in x for x in p['required_units']): raise Refused('units_schema')
    r=p['min_resources']
    if not isinstance(r,dict) or set(r)!={'cpu','ram','available','disk','inodes'} or any(type(v)!=int or v<=0 for v in r.values()): raise Refused('resources_schema')
    if type(p['max_update_age_hours'])!=int or not 1<=p['max_update_age_hours']<=168: raise Refused('update_age')
    return p

def nft_semantic(obj):
    """Rimuove solo metadati/handle/valori dei contatori, mai l'espressione counter."""
    if isinstance(obj,list):
        return [nft_semantic(v) for v in obj if not (isinstance(v,dict) and set(v)=={'metainfo'})]
    if isinstance(obj,dict):
        result={}
        for k,v in obj.items():
            if k=='handle': continue
            if k=='counter' and isinstance(v,dict):
                result[k]={a:nft_semantic(b) for a,b in v.items() if a not in ('packets','bytes')}
            else: result[k]=nft_semantic(v)
        return result
    return obj

def read_keys(p):
    if p.is_symlink(): raise CheckError('key_symlink')
    if not p.exists(): return []
    if p.is_symlink() or not p.is_file() or p.stat().st_size>65536: raise CheckError('key_path')
    return [l.strip() for l in p.read_text().splitlines() if l.strip() and not l.lstrip().startswith('#')]

def main():
    if len(sys.argv)!=1 or os.geteuid()!=0 or Path(__file__).absolute()!=BASE/'p0-preflight.py': raise Refused('canonical_root_only')
    trusted(BASE,True); trusted(Path(__file__)); trusted(POLICY,private=True)
    observations=diagnostics()
    pb=POLICY.read_bytes()
    if len(pb)>262144: raise Refused('policy_size')
    p=schema(json.loads(pb))
    if Path('/etc/machine-id').read_text().strip()!=p['machine_id']: raise Refused('machine_mismatch')
    trusted(LOGDIR,True,True)
    # Quota locale: nessuna nuova corsa quando lo spool è pieno, no auto-prune.
    entries=list(LOGDIR.iterdir())
    if len(entries)>=10000 or sum(x.lstat().st_size for x in entries)>=256*1024**2: raise Refused('log_quota')
    os.umask(0o077)
    lock=os.open(LOGDIR/'p0.lock',os.O_RDWR|os.O_CREAT|os.O_NOFOLLOW,0o600)
    s=os.fstat(lock)
    if s.st_uid!=0 or not stat.S_ISREG(s.st_mode) or s.st_mode&0o077: raise Refused('lock_path')
    try: fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
    except BlockingIOError: raise Refused('busy') from None
    run=uuid.uuid4().hex
    logpath=LOGDIR/('p0-'+run+'.jsonl')
    fd=os.open(logpath,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
    failed=[];observed=observations;current_check="p0_start"
    with os.fdopen(fd,'w') as log:
        def record(event,**data):
            log.write(json.dumps(dict(ts_utc=stamp(),run_id=run,event=event,**data),sort_keys=True)+'\n');log.flush();os.fsync(log.fileno())
        def check(name,ok):
            nonlocal current_check
            current_check=name
            record('check',name=name,status='PASS' if ok else 'FAIL')
            if not ok: failed.append(name)
        def command(args):
            nonlocal current_check
            current_check='command_'+Path(args[0]).name
            try:
                r=subprocess.run(args,env=ENV,stdin=subprocess.DEVNULL,capture_output=True,timeout=20)
            except (OSError,subprocess.TimeoutExpired): raise CheckError('command_unavailable') from None
            # Comandi sono fissi o presi dal profilo root; output mai riversato.
            record('command',program=args[0],rc=r.returncode,stdout_sha256=sha(r.stdout),stderr_sha256=sha(r.stderr))
            if r.returncode: raise CheckError('command_failed')
            if len(r.stdout)>4*1024*1024: raise CheckError('output_too_large')
            return r.stdout.decode()
        record('start',script_sha256=sha(Path(__file__).read_bytes()),policy_sha256=sha(pb),install_id=p['install_id'],service=p['service'])
        try:
            release=dict(l.split('=',1) for l in Path('/etc/os-release').read_text().splitlines() if '=' in l)
            check('debian13',release.get('ID','').strip('"')=='debian' and release.get('VERSION_ID','').strip('"')=='13')
            for path,digest in p['files'].items():
                trusted(path);check('file_'+path,sha(Path(path).read_bytes())==digest)
            # Due ancore distinte: autorizzazioni esecuzione vs ricevute banco.
            trusted('/etc/ambrogio-rbx2/allowed_signers')
            check('signer_anchor',Path('/etc/ambrogio-rbx2/allowed_signers').read_text().strip()=='codex namespaces="ambrogio-banco-v3" '+p['signer_key'])
            command(['/usr/sbin/sshd','-t'])
            unit='ambrogio-rbx2-emergency-ssh.service'
            fragment=command(['/usr/bin/systemctl','show',unit,'-p','FragmentPath','--value']).strip()
            dropins=command(['/usr/bin/systemctl','show',unit,'-p','DropInPaths','--value']).strip()
            envfiles=command(['/usr/bin/systemctl','show',unit,'-p','EnvironmentFiles','--value']).strip()
            start=command(['/usr/bin/systemctl','show',unit,'-p','ExecStart','--value'])
            check('ssh_effective_unit',fragment=='/etc/systemd/system/'+unit and not dropins and not envfiles and 'argv[]=/usr/bin/env -i PATH=/usr/sbin:/usr/bin:/sbin:/bin /usr/sbin/sshd -D -f /etc/ssh/sshd_config ;' in start)
            pid=int(command(['/usr/bin/systemctl','show',unit,'-p','MainPID','--value']).strip())
            proc=Path('/proc')/str(pid)
            check('ssh_live_process',pid>0 and str((proc/'exe').readlink())=='/usr/sbin/sshd' and b'/etc/ssh/sshd_config' in (proc/'cmdline').read_bytes())
            for stock in ('ssh.service','ssh.socket'):
                props=dict(l.split('=',1) for l in command(['/usr/bin/systemctl','show',stock,'-p','ActiveState','-p','UnitFileState']).splitlines() if '=' in l)
                check('stock_masked_'+stock,props.get('UnitFileState')=='masked' and props.get('ActiveState') in ('inactive','failed'))
            accounts=pwd.getpwall()
            check('uid_zero_unique',[a.pw_name for a in accounts if a.pw_uid==0]==['root'])
            trusted('/var/lib/ambrogio-rbx2/log-identity',True,True)
            trusted('/var/lib/ambrogio-rbx2/log-identity/key',private=True)
            for a in accounts:
                for c in p['ssh_contexts']:
                    ctx='user='+a.pw_name+',host='+c['host']+',addr='+c['addr']+',laddr='+c['laddr']+',lport=22'
                    out=command(['/usr/sbin/sshd','-T','-C',ctx])
                    effective={}
                    for line in out.splitlines():
                        k,_,v=line.partition(' ');effective.setdefault(k,[]).append(v)
                    required={'permitrootlogin':'no','passwordauthentication':'no','kbdinteractiveauthentication':'no',
                              'pubkeyauthentication':'yes','authorizedkeysfile':'/etc/ssh/authorized_keys/%u',
                              'authorizedkeyscommand':'none','trustedusercakeys':'none','allowusers':'debian',
                              'disableforwarding':'yes','permituserrc':'no','permituserenvironment':'no'}
                    check('ssh_'+a.pw_name+'_v'+str(ipaddress.ip_address(c['addr']).version),
                          all(effective.get(k)==[v] for k,v in required.items()) and not effective.get('acceptenv'))
                for keyfile in ('authorized_keys','authorized_keys2'):
                    check('no_home_keys_'+a.pw_name+'_'+keyfile,not read_keys(Path(a.pw_dir)/'.ssh'/keyfile))
                password=command(['/usr/bin/passwd','-S',a.pw_name]).split()
                check('password_locked_'+a.pw_name,len(password)>1 and password[1]=='L')
            keydir=Path('/etc/ssh/authorized_keys');trusted(keydir,True)
            check('key_directory_exact',sorted(x.name for x in keydir.iterdir())==['debian'])
            trusted(keydir/'debian')
            check('public_key_readable',keydir.stat().st_mode&0o777==0o755 and (keydir/'debian').stat().st_mode&0o777==0o644)
            check('emergency_only',read_keys(keydir/'debian')==['restrict,pty '+p['emergency_key']])
            command(['/usr/sbin/visudo','-c'])
            sudo_dir=Path('/etc/sudoers.d');trusted(sudo_dir,True)
            sudo_text=Path('/etc/sudoers').read_text()
            check('sudo_policy_complete','/etc/sudoers' in p['files'] and not any(l.strip().startswith(('#include','@include')) for l in sudo_text.splitlines()))
            # Nessun worker può elevare; debian è accesso umano di emergenza con sudo.
            for a in accounts:
                if a.pw_uid>=1000 and a.pw_name not in ('debian','nobody'):
                    groups=command(['/usr/bin/id','-nG',a.pw_name]).split()
                    check('no_privileged_groups_'+a.pw_name,not set(groups)&{'sudo','docker','adm','systemd-journal'})
            actual=json.loads(command(['/usr/sbin/nft','-s','-j','list','ruleset']))
            observed['nft_semantic']=nft_semantic(actual);observed['nft_sha256']=sha(json.dumps(observed['nft_semantic'],sort_keys=True).encode())
            check('nft_semantic',nft_semantic(actual)==nft_semantic(p['nft_semantic']))
            listener=[]
            for line in command(['/usr/bin/ss','-H','-lntu']).splitlines():
                parts=line.split()
                if len(parts)<5: raise CheckError('ss_format')
                listener.append([parts[0],parts[4],parts[1]])
            observed['listeners']=sorted(listener)
            observed['versions']={}
            for binary,args in [('sshd',['/usr/sbin/sshd','-V']),('sudo',['/usr/bin/sudo','-V']),('nft',['/usr/sbin/nft','--version'])]:
                vr=subprocess.run(args,env=ENV,capture_output=True,timeout=20)
                observed['versions'][binary]=(vr.stdout+vr.stderr).decode(errors='replace').splitlines()[0][:160]
            check('listeners_exact',sorted(listener)==sorted(p['allowed_listeners']))
            for package in ('unattended-upgrades','nftables','openssh-server'):
                check('installed_'+package,command(['/usr/bin/dpkg-query','-W','-f=${Status}',package]).strip()=='install ok installed')
            check('upgrade_binary',Path('/usr/bin/unattended-upgrade').is_file())
            apt=command(['/usr/bin/apt-config','dump'])
            check('updates_config','APT::Periodic::Unattended-Upgrade "1";' in apt and 'Unattended-Upgrade::Automatic-Reboot "false";' in apt)
            for unit in p['required_units']:
                props=dict(l.split('=',1) for l in command(['/usr/bin/systemctl','show',unit,'-p','LoadState','-p','ActiveState','-p','UnitFileState']).splitlines() if '=' in l)
                check('unit_'+unit,props.get('LoadState')=='loaded' and props.get('ActiveState')=='active' and props.get('UnitFileState')=='enabled')
            # Questo marker è creato solo dal wrapper che registra exit=0 dell'upgrade,
            # con impronta nel bundle: timestamp recente NON dimostra patch sufficienti.
            marker=Path('/var/lib/ambrogio-rbx2/security-update.json');trusted(marker,private=True)
            m=json.loads(marker.read_bytes())
            when=dt.datetime.fromisoformat(m['completed_utc'])
            age=(dt.datetime.now(dt.timezone.utc)-when).total_seconds()
            check('recent_update_success',m['exit_code']==0 and m['install_id']==p['install_id'] and 0<=age<=p['max_update_age_hours']*3600)
            upgrade_log=Path('/var/log/unattended-upgrades/unattended-upgrades.log')
            check('upgrade_log_metadata',upgrade_log.is_file() and 0<=dt.datetime.now(dt.timezone.utc).timestamp()-upgrade_log.stat().st_mtime<=p['max_update_age_hours']*3600)
            observed['reboot_required']=Path('/var/run/reboot-required').exists()
            record('reboot_status',required=observed['reboot_required'])
            check('no_pending_reboot',not Path('/var/run/reboot-required').exists())
            mem=dict(l.split(':',1) for l in Path('/proc/meminfo').read_text().splitlines())
            fs=os.statvfs('/var/lib');r=p['min_resources']
            check('resources',int(command(['/usr/bin/nproc','--all']).strip())>=r['cpu'] and int(mem['MemTotal'].split()[0])*1024>=r['ram'] and int(mem['MemAvailable'].split()[0])*1024>=r['available'] and fs.f_bavail*fs.f_frsize>=r['disk'] and fs.f_favail>=r['inodes'])
            rc=1 if failed else 3
            record('finish',verdict='FAIL' if failed else 'STATIC_PASS_EXTERNAL_PENDING',failed=failed,exit_code=rc)
        except (CheckError,Refused,ValueError,KeyError,TypeError,OverflowError) as exc:
            failed.append(current_check);record('finish',verdict='FAIL',failed=failed,error_type=type(exc).__name__,exit_code=1);rc=1
        except BaseException as exc:
            failed.append('p0_internal');record('finish',verdict='INTERNAL',failed=failed,error_type=type(exc).__name__,exit_code=4);rc=4
    publish_summary({'failed':failed,'observed':observed,'run_id':run,'p0_exit':rc})
    os.close(lock)
    print(json.dumps({'exit_code':rc,'log':str(logpath)}));return rc

def diagnostics():
    result={'reboot_required':Path('/var/run/reboot-required').exists(),'unavailable':[]}
    def capture(name,args):
        try:
            r=subprocess.run(args,env=ENV,capture_output=True,timeout=20)
            if r.returncode or len(r.stdout+r.stderr)>262144:raise ValueError('diagnostic_unavailable')
            return (r.stdout+r.stderr).decode(errors='replace')
        except (OSError,ValueError,subprocess.TimeoutExpired):
            result['unavailable'].append(name);return None
    nft=capture('nft',['/usr/sbin/nft','-s','-j','list','ruleset'])
    if nft:
        try:result['nft_semantic']=nft_semantic(json.loads(nft));result['nft_sha256']=sha(json.dumps(result['nft_semantic'],sort_keys=True).encode())
        except ValueError:result['unavailable'].append('nft_json')
    listeners=capture('listeners',['/usr/bin/ss','-H','-lntu'])
    if listeners:result['listeners']=sorted([line.split()[0],line.split()[4],line.split()[1]] for line in listeners.splitlines() if len(line.split())>=5)
    result['versions']={}
    for name,args in [('sshd',['/usr/sbin/sshd','-V']),('sudo',['/usr/bin/sudo','-V']),('nft',['/usr/sbin/nft','--version'])]:
        value=capture('version_'+name,args)
        if value:result['versions'][name]=value.splitlines()[0][:160]
    ssh=capture('ssh_defaults',['/usr/sbin/sshd','-T'])
    public_fields={'port','permitrootlogin','passwordauthentication','kbdinteractiveauthentication','pubkeyauthentication','authorizedkeysfile','authorizedkeyscommand','trustedusercakeys','allowusers','disableforwarding','permituserrc','permituserenvironment','acceptenv'}
    if ssh:result['ssh_defaults']=[line for line in ssh.splitlines() if line.partition(' ')[0] in public_fields]
    return result

def publish_summary(data):
    target=Path('/var/lib/ambrogio-rbx2/p0-summary.json')
    tmp=target.with_name('p0-summary-'+uuid.uuid4().hex+'.new')
    fd=os.open(tmp,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
    with os.fdopen(fd,'w') as f: json.dump(data,f,sort_keys=True);f.flush();os.fsync(f.fileno())
    os.replace(tmp,target)

if __name__=='__main__':
    try: result=main()
    except (Refused,ValueError,json.JSONDecodeError):
        print('P0 REFUSED; log assente o incompleto',file=sys.stderr);result=2
    except OSError:
        print('P0 LOG_IO; log assente o incompleto; ammissione chiusa',file=sys.stderr);result=5
    except BaseException:
        print('P0 INTERNAL; log assente o incompleto',file=sys.stderr);result=4
    if result in (2,4,5):
        try: publish_summary({'failed':['p0_refused' if result==2 else 'p0_internal' if result==4 else 'p0_log_io'],'observed':{},'p0_exit':result})
        except OSError: pass
    sys.exit(result)

