import http.server,ipaddress,json,os,pathlib,re,stat
PUBLIC=pathlib.Path('/var/lib/ambrogio-rbx2-public/current.json')
MAX=1048576

def read_public(name='current.json'):
 if name!='current.json' and not re.fullmatch(r'[a-f0-9]{64}\.json',name):raise ValueError('public_name')
 fd=os.open(PUBLIC.parent/name,os.O_RDONLY|os.O_NOFOLLOW)
 try:
  s=os.fstat(fd)
  if not stat.S_ISREG(s.st_mode) or s.st_uid!=0 or s.st_mode&0o022 or s.st_size>MAX: raise ValueError('public_file')
  with os.fdopen(fd,'rb',closefd=False) as f:return f.read(MAX+1)
 finally:os.close(fd)

class Handler(http.server.BaseHTTPRequestHandler):
 server_version='RBXReceipt/3';sys_version=''
 def log_message(self,*args):pass
 def setup(self):
  super().setup();self.connection.settimeout(5)
 def do_GET(self):
  if not re.fullmatch(r'/(?:current|[a-f0-9]{64})\.json',self.path) or str(ipaddress.ip_address(self.client_address[0]))!=self.server.agent_ip:
   self.send_error(404);return
  if self.headers.get('Transfer-Encoding') or self.headers.get('Content-Length') not in (None,'0'):
   self.send_error(400);return
  try:raw=read_public(self.path[1:])
  except (OSError,ValueError):self.send_error(503);return
  self.send_response(200);self.send_header('Content-Type','application/json');self.send_header('Content-Length',str(len(raw)));self.send_header('Cache-Control','no-store');self.send_header('Connection','close');self.end_headers();self.wfile.write(raw);self.close_connection=True
 # HEAD/POST/PUT/PATCH/DELETE/OPTIONS/CONNECT: BaseHTTPRequestHandler => 501.

if __name__=='__main__':
 c=json.loads(pathlib.Path('/etc/ambrogio-rbx2-reader.json').read_bytes())
 server=http.server.HTTPServer((str(ipaddress.IPv4Address(c['bank_ipv4'])),8443),Handler)
 server.agent_ip=str(ipaddress.ip_address(c['agent_egress_ip']))
 if ipaddress.ip_address(server.agent_ip).version!=4:raise ValueError('reader_ipv4_only')
 server.serve_forever(poll_interval=1)
